insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_opportunity','opportunity','noun','a time or situation when it is possible to do something you want to do','[{"senseId":"opportunity_1","meaning":"a time or situation when it is possible to do something you want to do","acceptedParaphrases":["chance","good moment"],"masteryContexts":[{"contextId":"u10_31_opportunity_meaning","text":"The summer job is an excellent opportunity to gain experience.","meaning":"a chance to do something useful","wrongMeanings":["a problem that cannot be solved","a rule that must be obeyed","a payment that must be made"]},{"contextId":"u10_31_opportunity_paraphrase","text":"Every child should have an equal opportunity to go to school, whatever their background.","meaning":"a fair chance that is open to everyone","wrongMeanings":["a rule that everyone must follow","a cost that everyone must pay","a test that everyone must pass"]}],"situationDistractors":["A broken leg stopped a boy from playing in the final.","Students had to wear school uniform every day.","A girl sent an email to the wrong person and could not get it back.","A girl missed the bus and had to walk.","A boy was told he could not join the team.","A student lost his ticket to the concert."],"gapDistractors":[{"contextId":"u10_31_opportunity_gap_1","answer":"opportunity","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_31_opportunity_gap_2","answer":"opportunity","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_31_opportunity_gap_3","answer":"opportunity","wrong":["loneliness","literacy","intonation"]}],"spellingErrors":["oppertunity","oportunity","opportunaty","opportunitey","oppotunity","opprtunity"],"masteryPassages":[{"passageId":"u10_31_opportunity_passage_1","contextId":"u10_31_opportunity_gap_1","text":"The exchange programme lets students live with a family in Spain. It is a wonderful ____ to improve their Spanish.","answer":"opportunity"},{"passageId":"u10_31_opportunity_passage_2","contextId":"u10_31_opportunity_gap_2","text":"Not every child in the world can go to school. Campaigners believe that every child deserves an equal ____ to learn.","answer":"opportunity"}],"contextDependentParaphrases":[],"wrongParaphrases":["obstacle","rule","mistake"],"misleadingDistractors":["a problem that stops you from acting","a rule that everyone must obey","a mistake that cannot be corrected"],"teacherNote":"Noun: a situation that makes it possible to do something (an opportunity to do something, take / miss an opportunity, job opportunities, equal opportunities). Countable. Boundary: opportunity is a good, often planned chance; chance can also mean luck or possibility."}]'::jsonb,'[]'::jsonb,'["an opportunity to","take the opportunity","equal opportunities"]'::jsonb,'live'),
('vocab_examination','examination','noun','a formal test of a student’s knowledge or ability in a subject','[{"senseId":"examination_1","meaning":"a formal test of a student’s knowledge or ability in a subject","acceptedParaphrases":["formal test","exam"],"masteryContexts":[{"contextId":"u10_32_examination_meaning","text":"Mobile phones are not allowed in the room during the examination.","meaning":"a formal test of knowledge","wrongMeanings":["an informal conversation","a lesson with a new teacher","a break between lessons"]},{"contextId":"u10_32_examination_paraphrase","text":"After the accident, the doctor carried out a full examination of the boy’s arm.","meaning":"a careful check of someone’s body","wrongMeanings":["an operation to fix the bone","a medicine to stop the pain","a bandage around the arm"]}],"situationDistractors":["A student had a relaxed chat with her teacher after class.","A boy bought a new revision guide in the bookshop.","The class went on a trip to the science museum.","A boy chatted with friends at lunch.","A girl browsed books in the library.","A class played a game in the playground."],"gapDistractors":[{"contextId":"u10_32_examination_gap_1","answer":"examination","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_32_examination_gap_2","answer":"examination","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_32_examination_gap_3","answer":"examination","wrong":["loneliness","recreation","literacy"]}],"spellingErrors":["examinasion","examanation","exammination","examinaton","exhamination","examinatoin"],"wordFamilyForms":[{"form":"examination","partOfSpeech":"noun","example":"The examination lasts two hours.","pedagogicallyUseful":true},{"form":"examine","partOfSpeech":"verb","example":"The doctor will examine your arm carefully.","pedagogicallyUseful":true,"altExample":"Scientists will examine the rocks brought back from Mars."},{"form":"examiner","partOfSpeech":"noun","example":"The examiner asked me to describe my hometown.","pedagogicallyUseful":true,"altExample":"Speak clearly so that the examiner can hear you."}],"masteryPassages":[{"passageId":"u10_32_examination_passage_1","contextId":"u10_32_examination_gap_1","text":"Students must arrive early and leave their phones in their bags. The ____ begins at nine o’clock and lasts two hours.","answer":"examination"},{"passageId":"u10_32_examination_passage_2","contextId":"u10_32_examination_gap_2","text":"After the fall, Tom’s arm was very painful. The doctor carried out a careful ____ before taking an X-ray.","answer":"examination"}],"contextDependentParaphrases":[],"wrongParaphrases":["informal chat","revision guide","school trip"],"misleadingDistractors":["an informal chat with a teacher","a book used for revision","a class trip to a museum"],"teacherNote":"Noun: a formal test of knowledge or ability (sit / take / pass / fail an examination); also a careful check (a medical examination). Countable. \"Exam\" is the common short form. The verb examine and the noun examiner are taught in the Word Family pathway."}]'::jsonb,'["examine","examiner"]'::jsonb,'["sit an examination","pass an examination","a final examination"]'::jsonb,'live'),
('vocab_research_10','research','noun','detailed study of a subject in order to discover new facts or information','[{"senseId":"research_10_1","meaning":"detailed study of a subject in order to discover new facts or information","acceptedParaphrases":["investigation","careful study to find facts"],"masteryContexts":[{"contextId":"u10_33_research_10_meaning","text":"The university is famous for its research into renewable energy.","meaning":"detailed scientific study","wrongMeanings":["advertising to attract students","teaching for young children","sport for local people"]},{"contextId":"u10_33_research_10_paraphrase","text":"Before writing your essay, do some research on the topic in the library.","meaning":"reading and studying to find information","wrongMeanings":["copying from a friend","guessing without checking","decorating the cover"]}],"situationDistractors":["A boy guessed the answer without reading the question.","A writer invented a funny story about a talking cat.","A student wrote a summary from memory without checking any facts.","A boy made up an answer without checking.","A girl repeated a rumour she had heard.","A student wrote a poem about the sea."],"gapDistractors":[{"contextId":"u10_33_research_10_gap_1","answer":"research","wrong":["loneliness","recreation","intonation"]},{"contextId":"u10_33_research_10_gap_2","answer":"research","wrong":["loneliness","recreation","intonation"]},{"contextId":"u10_33_research_10_gap_3","answer":"research","wrong":["loneliness","recreation","intonation"]}],"spellingErrors":["reserch","reasearch","researh","resaerch","reaserch","researsh"],"masteryPassages":[{"passageId":"u10_33_research_10_passage_1","contextId":"u10_33_research_10_gap_1","text":"Scientists have studied the sleep of thousands of teenagers. Their ____ shows that most teenagers do not get enough sleep.","answer":"research"},{"passageId":"u10_33_research_10_passage_2","contextId":"u10_33_research_10_gap_2","text":"Before you write your essay, find out as much as you can about the topic. Do your ____ using reliable books and websites.","answer":"research"}],"contextDependentParaphrases":[],"wrongParaphrases":["guesswork","fiction","gossip"],"misleadingDistractors":["a guess made without any evidence","a story invented for entertainment","a summary written from memory"],"teacherNote":"Noun: detailed study to discover new facts (do / carry out research, research into / on something, research shows that). Uncountable: not *a research or *researches. Also a verb (research a topic). Unit 10 uses it for academic study; Unit 9 taught it for reports and presentations. The noun researcher is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["do research","research into","research shows that"]'::jsonb,'live'),
('vocab_presentation','presentation','noun','a talk in which someone explains a subject to an audience, often using slides or pictures','[{"senseId":"presentation_1","meaning":"a talk in which someone explains a subject to an audience, often using slides or pictures","acceptedParaphrases":["talk","formal talk to an audience"],"masteryContexts":[{"contextId":"u10_34_presentation_meaning","text":"Her presentation on recycling included clear slides and a short video.","meaning":"a talk to an audience with information","wrongMeanings":["a written report handed in privately","a conversation between two friends","a test with no speaking"]},{"contextId":"u10_34_presentation_paraphrase","text":"The prize-giving ceremony ended with the presentation of the awards.","meaning":"the act of formally giving something to someone","wrongMeanings":["the selling of the awards","the design of the awards","the return of the awards"]}],"situationDistractors":["Two friends whispered to each other at the back of the bus.","Students wrote answers to a reading test in silence.","A teacher wrote the homework on the board.","A girl texted a friend.","A boy read silently on the bus.","A student did a written exercise alone."],"gapDistractors":[{"contextId":"u10_34_presentation_gap_1","answer":"presentation","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_34_presentation_gap_2","answer":"presentation","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_34_presentation_gap_3","answer":"presentation","wrong":["loneliness","literacy","recreation"]}],"spellingErrors":["presentasion","presantation","presentaton","presentashion","pressentation","presentaiton"],"wordFamilyForms":[{"form":"presentation","partOfSpeech":"noun","example":"Her presentation on recycling was excellent.","pedagogicallyUseful":true},{"form":"present","partOfSpeech":"verb","example":"Each group will present its findings to the class.","pedagogicallyUseful":true,"altExample":"Our group will present its project on Monday."},{"form":"presenter","partOfSpeech":"noun","example":"The television presenter introduced the next guest.","pedagogicallyUseful":true,"altExample":"The presenter of the podcast interviews a scientist every week."}],"masteryPassages":[{"passageId":"u10_34_presentation_passage_1","contextId":"u10_34_presentation_gap_1","text":"Each student must speak to the class for five minutes about a hobby. You can use slides to support your ____.","answer":"presentation"},{"passageId":"u10_34_presentation_passage_2","contextId":"u10_34_presentation_gap_2","text":"Dina stood at the front with her slides ready. She took a deep breath and began her ____ on renewable energy.","answer":"presentation"}],"contextDependentParaphrases":[],"wrongParaphrases":["private chat","written test","homework list"],"misleadingDistractors":["a private conversation between two friends","a written test with no speaking","a list of homework tasks"],"teacherNote":"Noun: a talk explaining a subject to an audience (give / make / do a presentation, a presentation on / about). Countable. A key speaking skill in this unit, linked with pronunciation and intonation. The verb present and the noun presenter are taught in the Word Family pathway."}]'::jsonb,'["present","presenter"]'::jsonb,'["give a presentation","a presentation on","a short presentation"]'::jsonb,'live'),
('vocab_pronunciation','pronunciation','noun','the way in which a word or language is spoken','[{"senseId":"pronunciation_1","meaning":"the way in which a word or language is spoken","acceptedParaphrases":["way of saying words","how words are spoken"],"masteryContexts":[{"contextId":"u10_35_pronunciation_meaning","text":"Listening to podcasts helped Carlos improve his English pronunciation.","meaning":"the way someone speaks a language","wrongMeanings":["the way someone spells words","the number of words someone knows","the speed someone writes"]},{"contextId":"u10_35_pronunciation_paraphrase","text":"The dictionary shows the pronunciation of each word using special symbols.","meaning":"how a particular word is said","wrongMeanings":["how a word is spelled","what a word means","where a word comes from"]}],"situationDistractors":["A student checked how many letters were in a long word.","A boy looked up what a new word meant in the dictionary.","A girl timed how fast she could read a page.","A student counted the pages in a book.","A boy copied a sentence neatly.","A girl underlined the title of her essay."],"gapDistractors":[{"contextId":"u10_35_pronunciation_gap_1","answer":"pronunciation","wrong":["loneliness","industry","literacy"]},{"contextId":"u10_35_pronunciation_gap_2","answer":"pronunciation","wrong":["loneliness","industry","literacy"]},{"contextId":"u10_35_pronunciation_gap_3","answer":"pronunciation","wrong":["loneliness","industry","employment"]}],"spellingErrors":["pronounciation","pronunsiation","pronunciasion","prononciation","pronuncation","pronunciaton"],"wordFamilyForms":[{"form":"pronunciation","partOfSpeech":"noun","example":"Her pronunciation has improved a lot.","pedagogicallyUseful":true},{"form":"pronounce","partOfSpeech":"verb","example":"How do you pronounce this word?","pedagogicallyUseful":true,"altExample":"Many learners find it hard to pronounce the sound “th”."},{"form":"mispronounce","partOfSpeech":"verb","example":"Visitors often mispronounce the name of our town.","pedagogicallyUseful":true,"altExample":"It is easy to mispronounce long scientific words."}],"masteryPassages":[{"passageId":"u10_35_pronunciation_passage_1","contextId":"u10_35_pronunciation_gap_1","text":"Paulo’s written English is excellent. However, people sometimes misunderstand him because his ____ is unclear.","answer":"pronunciation"},{"passageId":"u10_35_pronunciation_passage_2","contextId":"u10_35_pronunciation_gap_2","text":"The online dictionary has a small speaker symbol next to each word. If you click it, you can hear the correct ____.","answer":"pronunciation"}],"contextDependentParaphrases":[],"wrongParaphrases":["way of spelling words","meaning of words","speed of reading"],"misleadingDistractors":["the way words are spelled","the meaning of a word","the speed at which someone reads"],"teacherNote":"Noun: the way words or a language are spoken (good / clear pronunciation, the pronunciation of a word). Uncountable. Common spelling error: *pronounciation (the verb is pronounce, but the noun drops the o). The verb pronounce is taught in the Word Family pathway."}]'::jsonb,'["pronounce","mispronounce"]'::jsonb,'["clear pronunciation","the pronunciation of","practise pronunciation"]'::jsonb,'live'),
('vocab_intonation','intonation','noun','the rise and fall of the voice when speaking, which can change the meaning or show feelings','[{"senseId":"intonation_1","meaning":"the rise and fall of the voice when speaking, which can change the meaning or show feelings","acceptedParaphrases":["rise and fall of the voice","tone of voice"],"masteryContexts":[{"contextId":"u10_36_intonation_meaning","text":"A flat intonation can make a speaker sound bored or unfriendly.","meaning":"the way the voice goes up and down","wrongMeanings":["the speed at which someone speaks","the accent of a particular region","the number of words used"]},{"contextId":"u10_36_intonation_paraphrase","text":"In English, falling intonation usually shows that a statement is finished.","meaning":"the pattern of the voice at the end of a sentence","wrongMeanings":["the order of words in a sentence","the length of a sentence","the punctuation at the end of a sentence"]}],"situationDistractors":["A student counted the words in her essay.","A teacher changed the order of words on a slide.","A boy turned down the music in the next room.","A student checked her spelling.","A boy chose a font for his poster.","A girl measured the length of a table."],"gapDistractors":[{"contextId":"u10_36_intonation_gap_1","answer":"intonation","wrong":["employment","industry","literacy"]},{"contextId":"u10_36_intonation_gap_2","answer":"intonation","wrong":["employment","industry","literacy"]},{"contextId":"u10_36_intonation_gap_3","answer":"intonation","wrong":["employment","industry","loneliness"]}],"spellingErrors":["intonasion","intenation","intonaton","inttonation","intoneation","intonatoin"],"masteryPassages":[{"passageId":"u10_36_intonation_passage_1","contextId":"u10_36_intonation_gap_1","text":"You can often tell how someone feels from the way their voice rises and falls. Her ____ showed that she was not really happy.","answer":"intonation"},{"passageId":"u10_36_intonation_passage_2","contextId":"u10_36_intonation_gap_2","text":"In English, our voice usually goes up at the end of a yes/no question. This rising ____ shows the listener that we expect an answer.","answer":"intonation"}],"contextDependentParaphrases":[],"wrongParaphrases":["number of words","order of words","volume of noise"],"misleadingDistractors":["the number of words in a sentence","the order of words in a sentence","the loudness of background noise"],"teacherNote":"Noun: the rise and fall of the voice in speech (rising / falling intonation). Uncountable. Intonation shows questions, surprise, politeness or boredom. Boundary: pronunciation is how individual sounds and words are said; intonation is the pattern of the voice across a whole phrase."}]'::jsonb,'[]'::jsonb,'["rising intonation","falling intonation","flat intonation"]'::jsonb,'live'),
('vocab_vocabulary','vocabulary','noun','all the words that a person knows or uses, or all the words in a language','[{"senseId":"vocabulary_1","meaning":"all the words that a person knows or uses, or all the words in a language","acceptedParaphrases":["range of words","words a person knows"],"masteryContexts":[{"contextId":"u10_37_vocabulary_meaning","text":"Using a wide vocabulary in your essay will earn you higher marks.","meaning":"the range of words someone uses","wrongMeanings":["the grammar someone uses","the handwriting someone uses","the paragraphs someone uses"]},{"contextId":"u10_37_vocabulary_paraphrase","text":"Every science subject has its own special vocabulary that students must learn.","meaning":"the words used in a particular subject","wrongMeanings":["the equipment used in a laboratory","the books used in a subject","the rules used in experiments"]}],"situationDistractors":["A student checked that the verbs in her sentences were in the right order.","A boy practised saying difficult sounds in front of a mirror.","A teacher counted the spelling mistakes in an essay.","A student checked that his sentence had a full stop.","A girl practised the sound “th” in front of a mirror.","A boy timed how long his speech took."],"gapDistractors":[{"contextId":"u10_37_vocabulary_gap_1","answer":"vocabulary","wrong":["loneliness","recreation","employment"]},{"contextId":"u10_37_vocabulary_gap_2","answer":"vocabulary","wrong":["loneliness","recreation","employment"]},{"contextId":"u10_37_vocabulary_gap_3","answer":"vocabulary","wrong":["loneliness","recreation","employment"]}],"spellingErrors":["vocabulery","vocabularly","vocabluary","vocabularry","vocabularey","vocubulary"],"masteryPassages":[{"passageId":"u10_37_vocabulary_passage_1","contextId":"u10_37_vocabulary_gap_1","text":"Every week, Mei writes ten new words in a notebook and tests herself. As a result, her ____ has grown enormously.","answer":"vocabulary"},{"passageId":"u10_37_vocabulary_passage_2","contextId":"u10_37_vocabulary_gap_2","text":"Medicine has many difficult words. Medical students must learn a large amount of specialist ____.","answer":"vocabulary"}],"contextDependentParaphrases":[],"wrongParaphrases":["set of grammar rules","way of speaking","number of mistakes"],"misleadingDistractors":["the rules for putting words in order","the way words sound when spoken","the number of mistakes in a text"],"teacherNote":"Noun: the words a person knows or uses, or the words of a language or subject (a wide / limited vocabulary, increase your vocabulary, technical vocabulary). Usually uncountable in learning contexts. Boundary: vocabulary is words; grammar is how words are combined. Plural vocabularies is rare."}]'::jsonb,'[]'::jsonb,'["a wide vocabulary","increase your vocabulary","technical vocabulary"]'::jsonb,'live'),
('vocab_accurately','accurately','adverb','in a way that is correct and exact, without mistakes','[{"senseId":"accurately_1","meaning":"in a way that is correct and exact, without mistakes","acceptedParaphrases":["correctly","without mistakes"],"masteryContexts":[{"contextId":"u10_38_accurately_meaning","text":"The scientists measured the temperature accurately every hour.","meaning":"exactly, with no mistakes","wrongMeanings":["quickly and without care","loudly and clearly","occasionally and at random"]},{"contextId":"u10_38_accurately_paraphrase","text":"A good summary reports the writer’s ideas accurately and briefly.","meaning":"in a way that is true to the facts","wrongMeanings":["in a way that changes the meaning","at great length","in a way that copies every word"]}],"situationDistractors":["A boy rushed his homework and made lots of careless mistakes.","A girl shouted her answer before the teacher finished the question.","A student wrote such messy notes that nobody could read them.","A boy guessed the measurements without a ruler.","A girl wrote the wrong date on her work.","A student copied the numbers in the wrong order."],"gapDistractors":[{"contextId":"u10_38_accurately_gap_1","answer":"accurately","wrong":["reluctantly","lonely","overseas"]},{"contextId":"u10_38_accurately_gap_2","answer":"accurately","wrong":["reluctantly","lonely","nervously"]},{"contextId":"u10_38_accurately_gap_3","answer":"accurately","wrong":["reluctantly","lonely","rarely"]}],"spellingErrors":["accuratly","acurately","accuratelly","accuretely","accuratley","acuratly"],"wordFamilyForms":[{"form":"accurately","partOfSpeech":"adverb","example":"Measure each line accurately with a ruler.","pedagogicallyUseful":true},{"form":"accurate","partOfSpeech":"adjective","example":"The report gives an accurate picture of school life.","pedagogicallyUseful":true,"altExample":"Make sure your notes are accurate before the test."},{"form":"accuracy","partOfSpeech":"noun","example":"Examiners reward accuracy as well as range.","pedagogicallyUseful":true,"altExample":"The machine checks the accuracy of every measurement."}],"masteryPassages":[{"passageId":"u10_38_accurately_passage_1","contextId":"u10_38_accurately_gap_1","text":"In the science experiment, small mistakes can ruin the results. You must measure each liquid ____.","answer":"accurately"},{"passageId":"u10_38_accurately_passage_2","contextId":"u10_38_accurately_gap_2","text":"A good summary does not change the writer’s ideas. It reports them ____ and in fewer words.","answer":"accurately"}],"contextDependentParaphrases":[],"wrongParaphrases":["carelessly","loudly","unclearly"],"misleadingDistractors":["very quickly but carelessly","in a loud and confident way","in a way that is hard to understand"],"teacherNote":"Adverb: correctly and exactly (measure / describe / spell accurately). Linked to accurate (adjective) and accuracy (noun). Marking schemes reward using language accurately as well as widely. The adjective accurate and the noun accuracy are taught in the Word Family pathway."}]'::jsonb,'["accurate","accuracy"]'::jsonb,'["measure accurately","describe accurately","spell accurately"]'::jsonb,'live'),
('vocab_effectively','effectively','adverb','in a way that works well and produces the result that you want','[{"senseId":"effectively_1","meaning":"in a way that works well and produces the result that you want","acceptedParaphrases":["successfully","in a way that works well"],"masteryContexts":[{"contextId":"u10_39_effectively_meaning","text":"To communicate effectively, you need to listen as well as speak.","meaning":"in a way that achieves the aim","wrongMeanings":["in a way that wastes time","in a quiet and polite way","in a slow and careful way"]},{"contextId":"u10_39_effectively_paraphrase","text":"The poster campaign effectively reduced the amount of litter in the playground.","meaning":"with a successful result","wrongMeanings":["without any effect at all","by accident","for a short time only"]}],"situationDistractors":["A boy spent three hours on homework but did the wrong exercise.","A shop paid for a huge advert that nobody saw.","A girl explained her idea so badly that nobody understood.","A boy studied for hours but used the wrong notes.","A girl’s poster was so confusing that nobody understood it.","A plan to save money ended up costing more."],"gapDistractors":[{"contextId":"u10_39_effectively_gap_1","answer":"effectively","wrong":["reluctantly","lonely","overseas"]},{"contextId":"u10_39_effectively_gap_2","answer":"effectively","wrong":["reluctantly","lonely","overseas"]},{"contextId":"u10_39_effectively_gap_3","answer":"effectively","wrong":["lonely","overseas","academic"]}],"spellingErrors":["effectivly","efectively","effectivelly","effectivley","efectivly","effecktively"],"wordFamilyForms":[{"form":"effectively","partOfSpeech":"adverb","example":"She uses examples effectively in her essays.","pedagogicallyUseful":true},{"form":"effective","partOfSpeech":"adjective","example":"Mind maps are an effective way to revise.","pedagogicallyUseful":true,"altExample":"Regular practice is the most effective way to learn vocabulary."},{"form":"effectiveness","partOfSpeech":"noun","example":"The school measured the effectiveness of the new timetable.","pedagogicallyUseful":true,"altExample":"Teachers discussed the effectiveness of online lessons."}],"masteryPassages":[{"passageId":"u10_39_effectively_passage_1","contextId":"u10_39_effectively_gap_1","text":"Some students revise for hours without remembering much. Others use short, focused sessions and learn far more ____.","answer":"effectively"},{"passageId":"u10_39_effectively_passage_2","contextId":"u10_39_effectively_gap_2","text":"A good leader listens to the team and explains plans clearly. This helps everyone work together ____.","answer":"effectively"}],"contextDependentParaphrases":[],"wrongParaphrases":["slowly","expensively","secretly"],"misleadingDistractors":["in a slow and careful way","in an expensive way","in a way that nobody notices"],"teacherNote":"Adverb: in a way that produces the result wanted (communicate / work / use something effectively). Linked to effective (adjective) and effectiveness (noun). Boundary: effectively is about results; efficiently is about not wasting time or energy."}]'::jsonb,'["effective","effectiveness"]'::jsonb,'["communicate effectively","work effectively","use time effectively"]'::jsonb,'live'),
('vocab_evaluate_10','evaluate','verb','to judge how good, useful or successful something is after thinking about it carefully','[{"senseId":"evaluate_10_1","meaning":"to judge how good, useful or successful something is after thinking about it carefully","acceptedParaphrases":["assess","judge the value of"],"masteryContexts":[{"contextId":"u10_40_evaluate_10_meaning","text":"Use the checklist to evaluate your own essay before you hand it in.","meaning":"to judge how good something is","wrongMeanings":["to copy something without changes","to describe something without judging it","to share something with friends"]},{"contextId":"u10_40_evaluate_10_paraphrase","text":"The school will evaluate the new timetable after one term.","meaning":"to decide how successful something has been","wrongMeanings":["to cancel something immediately","to print something for everyone","to hide something from students"]}],"situationDistractors":["A student copied a paragraph from a website without reading it.","A boy described the film’s story but gave no opinion about it.","A girl threw away her test without looking at the feedback.","A boy accepted the first website he found without checking it.","A girl copied the instructions word for word.","A student forgot about the project as soon as it ended."],"gapDistractors":[{"contextId":"u10_40_evaluate_10_gap_1","answer":"evaluate","wrong":["succeed","reflect","communicate"]},{"contextId":"u10_40_evaluate_10_gap_2","answer":"evaluate","wrong":["succeed","contribute","communicate"]},{"contextId":"u10_40_evaluate_10_gap_3","answer":"evaluate","wrong":["succeed","contribute","communicate"]}],"spellingErrors":["evalute","evaluat","evalaute","evaluete","evluate","evalueate"],"masteryPassages":[{"passageId":"u10_40_evaluate_10_passage_1","contextId":"u10_40_evaluate_10_gap_1","text":"Not everything on the internet is true. Before using a website in your essay, ____ how reliable it is.","answer":"evaluate"},{"passageId":"u10_40_evaluate_10_passage_2","contextId":"u10_40_evaluate_10_gap_2","text":"The new timetable started in September. In December, the school will ____ whether it has been a success.","answer":"evaluate"}],"contextDependentParaphrases":[],"wrongParaphrases":["copy","describe","forget"],"misleadingDistractors":["to copy something without checking it","to describe something without giving an opinion","to forget about something quickly"],"teacherNote":"Verb: to judge the quality, value or success of something (evaluate a source, evaluate your own work, evaluate the evidence). A key command word in essays: evaluate means give strengths, weaknesses and a judgement. Unit 10 uses it for learning and courses; earlier units taught it for information and plans. The noun evaluation is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["evaluate a source","evaluate the evidence","evaluate your own work"]'::jsonb,'live')
